                      >
                        <ThumbsDown className="w-3 h-3 mr-1" />
                        Against
                      </Button>
                      <Button 
                        size="sm" 
                        variant="outline"
                        onClick={() => handleVote(dispute.id, 'abstain')}
                        className="flex-1"
                      >
                        <Minus className="w-3 h-3 mr-1" />
                        Abstain
                      </Button>
                    </div>
                  </div>
