                {dispute.status === 'under_review' && dispute.arbitrator && (
                  <div className="text-sm bg-blue-50 p-3 rounded">
                    <p className="font-medium">Under Review</p>
                    <p className="text-muted-foreground">Arbitrator: {dispute.arbitrator}</p>
