    if (score >= 50) return { level: 'Fair', color: 'text-yellow-600', icon: '👌' };
    return { level: 'Poor', color: 'text-red-600', icon: '⚠️' };
  };

  const handleSaveProfile = () => {
    updateProfile(editData);
    setIsEditing(false);
