                        />
                      </div>
                      <div className="space-y-2">
                        <Label>Country</Label>
                        <Input
                          value={editData.profile?.country || ''}
                          onChange={(e) => setEditData({ 
                            ...editData, 
                            profile: { ...editData.profile, country: e.target.value }
                          })}
                        />
                      </div>
                      <div className="space-y-2">
                        <Label>Postal Code</Label>
                        <Input
                          value={editData.profile?.postalCode || ''}
                          onChange={(e) => setEditData({ 
