          transfers: mockTransfers.filter(t => t.to === currentUser.name)
        };
      case 'authority':
      case 'arbitrator':
        return {
          parcels: mockLandParcels,
          disputes: mockDisputes,
          transfers: mockTransfers
        };
      default:
        return { parcels: [], disputes: [], transfers: [] };
