          paymentHistory: 95,
          creditUtilization: 25,
          lengthOfHistory: 88,
          newCredit: 82,
          creditMix: 90
        },
        financialProfile: {
          monthlyIncome: 8500,
          assets: 450000,
          liabilities: 125000,
          netWorth: 325000,
