                </div>
              );
            })}
            {userData.transfers.length === 0 && (
              <p className="text-sm text-muted-foreground text-center py-4">No transfers found</p>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Blockchain Network Status */}
      <RoleBasedAccess allowedRoles={['authority', 'arbitrator']}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Shield className="w-5 h-5" />
              Blockchain Network Status
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="text-center p-4 border rounded-lg bg-green-50">
                <div className="text-2xl font-bold text-green-600">99.9%</div>
                <p className="text-sm text-muted-foreground">Network Uptime</p>
              </div>
              <div className="text-center p-4 border rounded-lg bg-blue-50">
                <div className="text-2xl font-bold text-blue-600">2.3s</div>
                <p className="text-sm text-muted-foreground">Avg Block Time</p>
              </div>
              <div className="text-center p-4 border rounded-lg bg-purple-50">
                <div className="text-2xl font-bold text-purple-600">1,247</div>
                <p className="text-sm text-muted-foreground">Total Transactions</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </RoleBasedAccess>
    </div>
  );
};

const AuthPage = () => {
  const [isLogin, setIsLogin] = useState(true);

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-green-50 flex items-center justify-center p-4">
      <div className="w-full max-w-md space-y-6">
