  landParcelId: string;
  from: string;
  to: string;
  amount: number;
  status: 'pending' | 'escrowed' | 'completed' | 'cancelled';
  initiatedDate: string;
  completedDate?: string;
  escrowHash?: string;
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: 'landowner' | 'buyer' | 'authority' | 'arbitrator';
