                  You are logged in as a <span className="capitalize font-medium">{currentUser.role}</span>
                  {currentUser.reputation && (
                    <span className="ml-2">
                      • Reputation: <span className="font-medium">{currentUser.reputation.score}/100</span>
                    </span>
                  )}
                </p>
              </div>
              <div className="flex items-center gap-2">
                <Badge className="bg-blue-100 text-blue-800">
                  <Shield className="w-3 h-3 mr-1" />
                  {currentUser.verificationStatus}
                </Badge>
                {currentUser.reputation && (
                  <Badge variant="outline">
                    ⭐ {currentUser.reputation.score}
                  </Badge>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Stats Overview */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card className="border-blue-200 bg-gradient-to-br from-blue-50 to-blue-100">
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">
              {currentUser?.role === 'landowner' ? 'My Land Parcels' : 'Total Land Parcels'}
            </CardTitle>
            <MapPin className="h-4 w-4 text-blue-600" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-blue-700">{userData.parcels.length}</div>
            <p className="text-xs text-blue-600">Registered on blockchain</p>
