                </Badge>
                <p className="text-xs text-green-600">✓ Uploaded</p>
              </div>
              <div className="space-y-1">
                <Badge variant="outline" className="w-full justify-center">
                  <Camera className="w-3 h-3 mr-1" />
                  Face Scan
                </Badge>
                <p className="text-xs text-green-600">✓ Completed</p>
              </div>
              <div className="space-y-1">
                <Badge variant="outline" className="w-full justify-center">
